__NUXT_JSONP__("/de/how-to-apply/student-visa-f1", {data:[{details:{slug:"de",pageTitle:"Studentenvisum F1 | Mentor Language Institute",pageDescription:"Bitte wähle deine Situation aus den untenstehenden Optionen aus.",title:"Studentenvisum F1",image:"\u002Fimages\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Fvisa_application.jpg",subtitle:["Bitte wähle deine Situation aus den untenstehenden Optionen aus. \u003Cbr \u002F\u003EWenn du dir über deine Situation nicht sicher bist, klicke MEHR LESEN um weitere Details zu erfahren."],category:[{btn_visa:{image:"\u002Fimages\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Foverseas_btn_de.png",link:"\u002Fde\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Foverseas-students"},btn_transfer:{image:"\u002Fimages\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Ftransfer_student_btn_de.png",link:"\u002Fde\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Ftransfer-students"},btn_status:{image:"\u002Fimages\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Fchange_status_btn_de.png",link:"\u002Fde\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Fchange-of-status"}}],content:{subtitle:"Fragen?",description:["Im Normalfall benötigst du ein Studentenvisum um als Langzeitstudent in den USA zu bleiben.\u003Cbr \u002F\u003EWenn du nicht weisst, ob du ein Visum brauchst oder nicht, kontaktiere uns bitte.","Wir haben Mitarbeiter in 8 verschiedenen Sprachen."],imageLink:{image:"\u002Fimages\u002Fhow-to-apply\u002Fhow-to-apply\u002Fcontact-us-de.png",link:"\u002Fde\u002Fcontact"}},dir:"\u002Fstudent-visa-f1",path:"\u002Fstudent-visa-f1\u002Fde",extension:".json",createdAt:"2026-10-22T16:31:31.130Z",updatedAt:"2025-05-26T12:06:27.924Z"}}],fetch:{},mutations:void 0});